const soloMatch = text => {
  // Words match at the start of a word ("danc" matches "dancing"); a trailing $ means the whole word only ("read$").
  const t = text.toLowerCase(), has = list => list.filter(w => new RegExp(`\\b${w.replace(/\$$/, '').replace(/[.*+?^()[\]{}|\\]/g, '\\$&')}${w.endsWith('$') ? '\\b' : ''}`).test(t)).length;
  // Where a topic's first keyword appears in the text; ties go to whatever they typed first.
  const pos = list => Math.min(...list.map(w => t.search(new RegExp(`\\b${w.replace(/\$$/, '').replace(/[.*+?^()[\]{}|\\]/g, '\\$&')}`))).filter(n => n >= 0));
  let hits = SOLO_TOPICS.map(topic => ({ topic, score: has(topic.words) * (topic.also ? (has(topic.also) ? 3 : 0) : 1), at: pos(topic.words) }))
    .filter(x => x.score > 0).sort((a, b) => b.score - a.score || a.at - b.at);
  // A specific topic can replace a general one (e.g. "scary movie" drops the general movie list).
  const dropped = new Set(hits.flatMap(x => x.topic.over || []));
  hits = hits.filter(x => !dropped.has(x.topic.id));
  // Specific asks (like "sad movie") go first, then activities, then feelings. Within a tier, topics take turns.
  const turns = lists => Array.from({ length: Math.max(0, ...lists.map(l => l.length)) }, (_, r) => lists.map(l => l[r]).filter(Boolean)).flat();
  // byText topics (takeout) put ideas whose tags appear in the text first: "thai takeout" -> Thai card first.
  // Cuisine recipe lists end with a matching delivery card ("thai food" -> Thai takeout last).
  const takeoutCard = key => (SOLO_TOPICS.find(x => x.id === 'takeout').ideas.find(r => r[5].includes(key)));
  // Within a list, ideas whose name or tags contain one of their words go first ("ramen" -> the ramen recipe first).
  const said = t.split(/[^a-z]+/).filter(w => w.length >= 4 && !['recipe', 'recipes', 'takeout', 'food', 'want', 'some', 'something', 'with', 'good', 'ideas', 'night', 'delivery', 'order'].includes(w));
  const fits = r => said.some(w => r[1].toLowerCase().includes(w) || r[5].slice(1).some(g => String(g).toLowerCase().includes(w)));
  const ordered = x => [...[...x.topic.ideas].sort((a, b) => fits(b) - fits(a)),
    ...(x.topic.takeout ? [takeoutCard(x.topic.takeout)].filter(Boolean) : [])];
  const mixed = [...hits.filter(x => x.topic.also || x.topic.exact).flatMap(ordered),
    ...turns(hits.filter(x => x.topic.first && !x.topic.exact).map(x => x.topic.ideas)),
    ...turns(hits.filter(x => !x.topic.also && !x.topic.first && !x.topic.exact).map(x => x.topic.ideas))];
  return soloIdeas(mixed);
};
// Full local search: typed words + picks -> ideas. Budget/time can also come from the words ("free", "cheap", "quick").
const soloLocal = (query, picks = {}) => {
  const q = query.toLowerCase();
  const budget = picks.budget || (/\b(free|no money)\b/.test(q) ? 'free' : /\b(cheap|budget|inexpensive)\b/.test(q) ? '$' : '');
  const time = picks.time || (/\b(quick|short|fast|15 min|30 min)\b/.test(q) ? 'quick' : '');
  let found = query ? soloMatch(query) : [];
  if (!found.length && (budget || time)) found = soloIdeas(SOLO_TOPICS.flatMap(t => t.ideas).sort(() => Math.random() - .5));
  const fits = soloFilter(found, { budget, time });
  return { ideas: (fits.length ? fits : found).slice(0, 24), loosened: found.length > 0 && !fits.length };
};
const soloIdeas = rows => rows.filter((i, n, all) => all.findIndex(j => j[1] === i[1]) === n)
  .map(([emoji, title, description, cost, duration, tags, link, linkLabel, extra]) => ({ emoji, title, description, cost, duration, tags, vibe: tags[0], mode: 'solo', link: link || undefined, linkLabel: linkLabel || undefined, ...(extra || {}) }));
// Budget / time filters. Durations like "1h 45m", "30 min", "all night" -> minutes.
const soloCost = c => ({ free: 0, $: 1, $$: 2, $$$: 3 })[c] ?? 1;
const soloMinutes = d => /all night|forever/i.test(d || '') ? 999
  : ((+((d || '').match(/([\d.]+)\s*h/) || [])[1] || 0) * 60) + (+((d || '').match(/(\d+)\s*m/) || [])[1] || 0) || 60;
const SOLO_FILTERS = {
  who: { label: 'Who', icon: '👥', options: [['🙋', 'just me'], ['💕', 'date'], ['👯', 'friends'], ['👨‍👩‍👧', 'family']] },
  budget: { label: 'Budget', icon: '💰', options: [['🆓', 'free'], ['💵', '$'], ['💵', '$$'], ['💎', '$$$']] },
  time: { label: 'Time', icon: '⏰', options: [['⚡', 'quick'], ['🕐', 'couple hours'], ['🌙', 'all night']] },
};
const soloFilter = (ideas, { budget, time }) => ideas.filter(i =>
  (!budget || soloCost(i.cost) <= soloCost(budget)) &&
  (!time || time === 'all night' || soloMinutes(i.duration) <= (time === 'quick' ? 30 : 150)));
const SOLO_ACTIVITIES = [['🎮', 'games'], ['🎬', 'movies & tv'], ['🎵', 'songs'], ['💃', 'dancing'], ['🍳', 'cooking'], ['📍', 'going out'], ['📚', 'books'], ['🧁', 'desserts'], ['🛵', 'takeout'], ['🍷', 'girls night']];
const SOLO_MOODS = [['😄', 'happy'], ['😢', 'sad'], ['😴', 'tired'], ['🥳', 'social'], ['⚡', 'wired'], ['💸', 'broke'],
  ['🧭', 'adventurous'], ['💕', 'romantic'], ['🛋️', 'cozy'], ['😤', 'stressed']];

const soloTitle = i => String(i.title || '').replace(/^watch\s+/i, '').replace(/^"(.*)"$/, '$1');
const soloBg = title => {
  const hue = [...title].reduce((h, c) => (h * 31 + c.charCodeAt(0)) % 360, 17);
  return `background: radial-gradient(circle at 30% 20%, hsl(${hue} 80% 62%), hsl(${(hue + 50) % 360} 60% 30%) 60%, #14152c)`;
};
// Play link for games, "where to watch" for movies, nothing otherwise.
const soloWatch = i => /^https:\/\//.test(i.link || '') ? `<a class="solo-watch" target="_blank" rel="noopener" href="${ui.esc(i.link)}">${ui.esc(i.linkLabel || '🎮 Play now')}</a>`
  : (i.tags || []).some(t => /^(movie|film|tv)$/i.test(t)) ? `<a class="solo-watch" target="_blank" rel="noopener" href="https://www.justwatch.com/us/search?q=${encodeURIComponent(soloTitle(i))}">▶ Where to watch</a>` : '';

